queue = sort(requirements, key=score, desc=True)
for req in queue:
    for mould in compatible_moulds(req.article):
        machine = first(m for m in machines_for(mould) if m.capacity_left >= 1)
        if machine:
            qty = min(req.qty, machine.capacity_left)
            schedule.add(machine, mould, req, qty)
            machine.capacity_left -= qty; req.qty -= qty
        if req.qty == 0: break
    if req.qty > 0:
        backlog.add(req, reason="capacity / no compatible mould")

known = load_state()                         # key -> etag
for key, obj in list_bucket(prefix):
    status[key] = "NEW" if key not in known else ("REPLACED" if obj.etag != known[key] else "UNCHANGED")
latest = newest_by(stem, objs)
for row in master:
    obj = latest.get(stem(row.image_name))
    if not obj: row.absent = True; continue
    row.matched = obj
    if status[obj.key] != "UNCHANGED" or not exists_local(obj):
        try: download(obj)
        except AccessError as e: row.error = e; continue   # retried next run
    stage_state(obj)
upsert_state(objs); write_reports()

thumbs = parallel_map(make_thumb, unique(rows.image_code), workers=32)
r = start = 1; prev = None
for row in rows:
    write_text_cells(r, row)
    if row.code != prev:
        if prev and r - 1 > start: merge(start, r - 1, IMG_COL)
        insert_image(r, IMG_COL, thumbs.get(row.code)) or write(r, IMG_COL, "No image")
        prev, start = row.code, r
    r += 1
close_last_group(); spawn(record_missing, rows, thumbs)

